Q: It is possible to push page and set up back page with Navigator? A: <pre><code>      // Step 1:
      // Navigate to the Third Page and remove Splash Page from the stack
      Navigator.pushAndRemoveUntil(
          context,
          MaterialPageRoute(builder: (context) =&gt; ThirdPage()),
          (route) =&gt; false, // Removes all previous routes
        );

       // Step 2:
       // Navigate to the Second Page
        Navigator.push(
          context,
          MaterialPageRoute(builder: (context) =&gt; SecondPage()),
        );

      // Step 3: for third page
      onWillPop: () async {
      // Navigate to the Second Page when back button is pressed
       Navigator.push(
        context,
        MaterialPageRoute(builder: (context) =&gt; SecondPage()),
      );
    return false; // Prevent default back button behavior
</code></pre>

Q: Creating buttons with style class and onclick functions only by using javascript. Can it be done smarter? A: <p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false" data-babel-preset-react="false" data-babel-preset-ts="false">
<div class="snippet-code">
<pre class="snippet-code-js lang-js prettyprint-override"><code>function numberClicked(evt) {
  console.log(evt.target.dataset.value);
}

function plus() {
  console.log('plus');
}
var operations = [{
  data: '0',
  operation: numberClicked
}, {
  data: '1',
  operation: numberClicked
}, {
  data: '2',
  operation: numberClicked
}, {
  data: '+',
  operation: plus,
  tooltip: 'PLUS'
}, ];


var out = document.getElementById("out");
operations.forEach(function (option) {
  var btn = document.createElement("button");
  btn.type = "button";
  btn.dataset.value = option.data;
  btn.textContent = option.data;
  btn.addEventListener("click", option.operation);
  if (btn.tooltip) btn.title = btn.tooltip;
  out.appendChild(btn);
});</code></pre>
<pre class="snippet-code-html lang-html prettyprint-override"><code>&lt;div id="out"&gt;&lt;/div&gt;</code></pre>
</div>
</div>
</p>
